//! ft-sys — FFI declarations for the bundled FreeType library surface.
//!
//! Auto-generated by `generate_bindings.sh` (bindgen over `wrapper.h`, which
//! replicates the exact FreeType include set `win32ss/gdi/ntgdi/freetype.c`
//! uses) for all 3 architectures. This is the FreeType analog of `win32k-sys`
//! / `ntkrnl-sys`: freetype.c is the *only* win32k file that talks to FreeType,
//! and without byte-exact FT/TT type layouts + the full function surface the
//! translator would invent the ~42 FT functions, ~20 FT types and the FT_HAS_*
//! macros per-file, inconsistently and with wrong struct offsets.
//!
//! Use `ft_sys::ft::*`. NOT a standalone static library — an rlib declaration
//! dependency that links against the cmake-built FreeType `.a`.

#![no_std]
#![allow(non_snake_case, non_camel_case_types, non_upper_case_globals)]
#![allow(clippy::upper_case_acronyms)]
#![allow(dead_code)]

#[cfg(target_arch = "aarch64")]
mod bindgen_arm64;
#[cfg(target_arch = "x86_64")]
mod bindgen_amd64;
#[cfg(target_arch = "x86")]
mod bindgen_i386;

pub mod ft {
    #[cfg(target_arch = "aarch64")]
    pub use super::bindgen_arm64::*;
    #[cfg(target_arch = "x86_64")]
    pub use super::bindgen_amd64::*;
    #[cfg(target_arch = "x86")]
    pub use super::bindgen_i386::*;

    // FT_HAS_*/FT_IS_* are function-like macros (freetype.h) that bindgen drops.
    // They test `face->face_flags` bits; reimplement the 7 freetype.c uses.
    // C returns the masked int (used in boolean context) — we return bool.
    macro_rules! ft_face_flag_test {
        ($name:ident, $flag:ident) => {
            #[inline]
            pub unsafe fn $name(face: FT_Face) -> bool {
                (*face).face_flags & ($flag as FT_Long) != 0
            }
        };
    }
    ft_face_flag_test!(FT_HAS_KERNING, FT_FACE_FLAG_KERNING);
    ft_face_flag_test!(FT_HAS_VERTICAL, FT_FACE_FLAG_VERTICAL);
    ft_face_flag_test!(FT_HAS_FIXED_SIZES, FT_FACE_FLAG_FIXED_SIZES);
    ft_face_flag_test!(FT_HAS_MULTIPLE_MASTERS, FT_FACE_FLAG_MULTIPLE_MASTERS);
    ft_face_flag_test!(FT_IS_SCALABLE, FT_FACE_FLAG_SCALABLE);
    ft_face_flag_test!(FT_IS_SFNT, FT_FACE_FLAG_SFNT);
    ft_face_flag_test!(FT_IS_FIXED_WIDTH, FT_FACE_FLAG_FIXED_WIDTH);
}
